#!/usr/bin/env python3
# ---------------------------------------------------------------------------
# pocket-voxel patcher: working POKeDEX (patcher 3, standalone). TS-only.
#
# Ports gen1recomp src/ui/PokedexMenu.lua (dex-ordered contents list with
# seen/owned markers + SEEN/OWN counts + page-jump) and src/ui/DexEntryMenu.lua
# (the DATA page: front sprite, name, kind, height/weight and flavor text, all
# gated on the mon being owned).  Wires the START-menu POKeDEX pick (previously
# a no-op) to a new PokedexState, adds the pic()/scene render, and plays real
# cries on CRY.  AREA (Town Map) and PRNT (Yellow printer) are omitted -- their
# subsystems do not exist in this port.
#
# Adds one new file (voxelmon/game/ui/pokedexscreen.ts) and edits game.ts +
# scene.ts.  Independent of patchers 1-2.  Idempotent; aborts if an anchor is
# missing/ambiguous.  Run from ~/pocket-voxel: python3 apply_pokedex.py
# ---------------------------------------------------------------------------
import base64, sys, os
EDITS = [{'path': 'voxelmon/game/game.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/game.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/game.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/game.ts', 'old': 'CiAgcGFydHkoKTogdW5rbm93biB7CiAgICBjb25zdCB0b3AgPSB0aGlzLnN0YWNrW3RoaXMuc3RhY2subGVuZ3RoIC0gMV0gYXMgYW55OwogICAgcmV0dXJuIHRvcD8ua2luZCA9PT0gInBhcnR5IiA/IHRvcC52aWV3KCkgOiBudWxsOwogIH0KCiAgc3VtbWFyeSgpOiB1bmtub3duIHsKICAgIGNvbnN0IHRvcCA9IHRoaXMuc3RhY2tbdGhpcy5zdGFjay5sZW5ndGggLSAxXSBhcyBhbnk7Cg==', 'new': ''}, {'path': 'voxelmon/game/scene.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/scene.ts', 'old': '', 'new': ''}]
NEWFILES = [{'path': 'voxelmon/game/ui/pokedexscreen.ts', 'content': ''}]
def main():
    root=os.getcwd()
    if not os.path.isdir(os.path.join(root,"voxelmon")):
        sys.exit("! run this from the pocket-voxel repo root (no ./voxelmon here)")
    changed=skipped=0
    # new files first (the edits don't depend on them, but this keeps a partial
    # run coherent)
    for nf in NEWFILES:
        fp=os.path.join(root,nf["path"]); content=base64.b64decode(nf["content"]).decode()
        if os.path.isfile(fp):
            if open(fp,encoding="utf-8").read()==content: skipped+=1; continue
            sys.exit(f"! {nf['path']} already exists with different contents -- aborting\n  (remove it to re-apply, or you are on a diverged tree)")
        os.makedirs(os.path.dirname(fp),exist_ok=True)
        open(fp,"w",encoding="utf-8").write(content); changed+=1; print(f"  created {nf['path']}")
    by_file={}
    for h in EDITS: by_file.setdefault(h["path"],[]).append(h)
    for path,hs in by_file.items():
        fp=os.path.join(root,path)
        if not os.path.isfile(fp): sys.exit(f"! missing file: {path}")
        text=open(fp,encoding="utf-8").read(); orig=text
        for h in hs:
            old=base64.b64decode(h["old"]).decode(); new=base64.b64decode(h["new"]).decode()
            if new in text: skipped+=1; continue
            n=text.count(old)
            if n==0: sys.exit(f"! anchor not found in {path}\n  (not the expected tree, or already diverged)")
            if n>1: sys.exit(f"! anchor is ambiguous in {path} ({n} matches) -- aborting")
            text=text.replace(old,new,1); changed+=1
        if text!=orig: open(fp,"w",encoding="utf-8").write(text); print(f"  patched {path}")
    print(f"done: {changed} change(s) applied, {skipped} already present")
    if changed==0 and skipped: print("(nothing to do -- patcher already applied)")
if __name__=="__main__": main()
